    elif mode == 2:
        v = draw(st.integers(-1000, 1000))
        energy = [v] * n
    elif mode == 3:
        energy = sorted(draw(st.integers(-1000, 1000)) for _ in range(n))
    else:
        energy = sorted((draw(st.integers(-1000, 1000)) for _ in range(n)), reverse=True)
    k = draw(st.integers(1, n - 1))
    return f"{json.dumps(energy)}\n{k}\n"

