import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(2, 8))
    kind = draw(st.sampled_from(["random", "allequal", "negative", "sorted", "extreme"]))
    if kind == "allequal":
        v = draw(st.integers(-1000, 1000))
        energy = [v] * n
    elif kind == "negative":
        energy = draw(st.lists(st.integers(-1000, -1), min_size=n, max_size=n))
    elif kind == "sorted":
        energy = sorted(draw(st.lists(st.integers(-1000, 1000), min_size=n, max_size=n)))
    elif kind == "extreme":
        energy = draw(st.lists(st.sampled_from([-1000, 1000, 0, -1, 1]), min_size=n, max_size=n))
    else:
        energy = draw(st.lists(st.integers(-1000, 1000), min_size=n, max_size=n))
    k = draw(st.integers(1, n - 1))
    return f"{json.dumps(energy)}\n{k}\n"

def validate(inp):
    lines = inp.split("\n")
    # allow trailing newline only
    while lines and lines[-1] == "":
        lines.pop()
    if len(lines) != 2:
        return False
    try:
        energy = json.loads(lines[0])
        k = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(energy, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    n = len(energy)
    if n < 2 or n > 10**5:
        return False
    for x in energy:
        if not isinstance(x, int) or isinstance(x, bool) or not (-1000 <= x <= 1000):
            return False
    return 1 <= k <= n - 1

def ref(inp):
    lines = [l for l in inp.split("\n") if l != ""]
    energy = json.loads(lines[0])
    k = json.loads(lines[1])
    n = len(energy)
    best = None
    for s in range(n):
        total = 0
        i = s
        while i < n:
            total += energy[i]
            i += k
        if best is None or total > best:
            best = total
    return json.dumps(best)
